/* ===== S1788 LP pasto kodas (2026-10-19, Raimio „taisyk“) =====
 * LP Express įskiepis kasoje (woocommerce_checkout_process, prioritetas 10) siunčia adresą į LP API.
 * LP API priima tik 5 simbolių pašto kodą; „LT-12345“, „LT12345“, „12 345“ atmeta → klientas mato
 * angliškai „Please fill correct shipping data: postalCode ...“ ir užsakymas nesukuriamas.
 * Čia (prioritetas 1, prieš LP) LT adreso pašto kodą paverčiame 5 skaitmenimis, jei jų yra lygiai 5.
 * Kitokius (pvz. 4 ar 6 skaitmenys) paliekame – tada klaida teisinga. Išjungti: option ps_lp_pk_isjungta=1.
 */
if ( ! function_exists( 'petshop_lp_pk_normalizuoti' ) ) {
	function petshop_lp_pk_normalizuoti( $reiksme ) {
		$d = preg_replace( '/\D+/', '', (string) $reiksme );
		return ( strlen( $d ) === 5 ) ? $d : (string) $reiksme;
	}
	add_action( 'woocommerce_checkout_process', function () {
		if ( get_option( 'ps_lp_pk_isjungta' ) ) { return; }
		foreach ( array( 'billing', 'shipping' ) as $p ) {
			$k = $p . '_postcode';
			if ( empty( $_POST[ $k ] ) ) { continue; }
			$salis = isset( $_POST[ $p . '_country' ] ) ? strtoupper( (string) $_POST[ $p . '_country' ] ) : 'LT';
			if ( $salis !== 'LT' ) { continue; }
			$_POST[ $k ] = petshop_lp_pk_normalizuoti( wp_unslash( $_POST[ $k ] ) );
		}
	}, 1 );
}
